CREATE OR REPLACE FUNCTION public.get_self_savings_if_changed(p_known_version text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); af uuid:=public.get_effective_affiliate_id(); context jsonb; imp jsonb;
begin
 if actor is null or af is null then raise exception 'SAVINGS_AFFILIATE_REQUIRED' using errcode='42501';end if;
 if exists(select 1 from public.savings_publication_state where id and mode='PRIVATE') then
  return public.savings_if_changed_before_publication(p_known_version);
 end if;
 select to_jsonb(i) into imp from public.get_impersonation_context()i;
 context:=jsonb_build_object('actor_auth_user_id',actor,'effective_affiliate_id',af,'actor_session_id',auth.jwt()->>'session_id','impersonation_id',imp->>'session_id');
 -- Published accounts use a fresh dependency graph. No local value can
 -- outlive the atomic authority change or a confirmed real receipt.
 return jsonb_build_object('version',null,'modified',true,'cacheable',false,'context',context,'data',public.get_self_savings_live_readonly());
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_workspace_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare summary jsonb; pending bigint; conflicts bigint; periods jsonb; requests bigint; decisions bigint; deliveries bigint;
begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_READ_DENIED' using errcode='42501';end if;
 summary:=public.get_admin_savings_panel('padron','','todos',0,1);
 with due as materialized(select * from public.savings_workspace_receipts(null)),
 grouped as(select contribution_date date,count(*) count,sum(expected_amount) expected_amount from due where not has_actual group by contribution_date)
 select (select count(*) from due where not has_actual),(select count(*) from due where conflict),
  coalesce((select jsonb_agg(to_jsonb(g) order by g.date) from grouped g),'[]'::jsonb) into pending,conflicts,periods;
 select count(*) filter(where r.status in ('SUBMITTED','UNDER_REVIEW')),
  count(*) filter(where r.status='APPROVED' and r.request_type in ('WITHDRAW','EXTRAORDINARY_WITHDRAWAL')) into decisions,deliveries
 from public.savings_requests r join public.savings_participants p on p.id=r.participant_id
 where p.data_classification='CANONICAL' and r.data_classification='CANONICAL' and r.metadata->>'origin'='SAVINGS_RUNTIME_V1';
 -- An approved TERMINATE already schedules cessation; it has no delivery step.
 requests:=decisions+deliveries;
 return jsonb_build_object('kpis',summary->'kpis','collection_status',summary->'collection_status','publication_mode',summary->'publication_mode',
  'attention',jsonb_build_object('pending_receipts',pending,'receipt_conflicts',conflicts,'request_count',requests,
   'pending_decisions',decisions,'awaiting_delivery',deliveries,'periods',periods),'today',public.savings_operation_today());
end $function$

CREATE OR REPLACE FUNCTION public.get_self_savings_live_readonly()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare af uuid:=public.get_effective_affiliate_id(); pid uuid; mode text; result jsonb; control text;
begin
 if auth.uid() is null or af is null then raise exception 'SAVINGS_AFFILIATE_REQUIRED' using errcode='42501';end if;
 select s.mode into mode from public.savings_publication_state s where id;
 if mode='PRIVATE' then return public.savings_self_before_publication();end if;
 if mode is distinct from 'PUBLISHED' then raise exception 'SAVINGS_PUBLICATION_STATE_REQUIRED';end if;
 select a.numero_control into control from public.affiliates a where a.id=af and not coalesce(a.is_archived,false);
 if nullif(btrim(control),'') is null or (select count(*) from public.affiliates where numero_control=control and not coalesce(is_archived,false))<>1 then
  raise exception 'SAVINGS_EXACT_IDENTITY_REQUIRED' using errcode='55000';end if;
 if exists(select 1 from public.savings_participants p where (p.affiliate_id=af or p.legacy_folio=control)
  and (p.affiliate_id is distinct from af or p.legacy_folio is distinct from control)) then
  raise exception 'SAVINGS_EXACT_IDENTITY_REQUIRED' using errcode='55000';end if;
 select p.id into pid from public.savings_participants p join public.affiliates a on a.id=p.affiliate_id
  where a.id=af and p.legacy_folio=a.numero_control;
 if pid is null then
  if exists(select 1 from public.savings_review_records r join public.affiliates a on a.numero_control=r.source_folio where a.id=af and r.source_sheet='Ahorro') then
   raise exception 'SAVINGS_EXACT_IDENTITY_REQUIRED';end if;
  return jsonb_build_object('schema_version','SAVINGS_CERTIFIED_SELF_V1','authority','SUPABASE','projection','CERTIFIED_OPERATION','cutover_status','PUBLISHED',
   'participant',null,'enrollment',null,'balances',null,'annual','[]'::jsonb,'history','[]'::jsonb,'withdrawals','[]'::jsonb,'beneficiaries','[]'::jsonb,'upcoming','[]'::jsonb,'requests','[]'::jsonb,
   'actions',jsonb_build_object('JOIN',public.savings_effective_action('JOIN',null),'CHANGE_AMOUNT',false,'WITHDRAW',false,'TERMINATE',false),
   'write_capabilities',jsonb_build_object('requests',true,'beneficiaries',false));
 end if;
 return public.savings_canonical_user_projection(pid);
end $function$

CREATE OR REPLACE FUNCTION public.savings_effective_action(p_action_code text, p_participant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.savings_action_availability%rowtype; mode text;
begin
 select * into a from public.savings_action_availability
 where action_code=p_action_code and scope_type='PARTICIPANT' and participant_id=p_participant_id
   and effective_from<=now() order by effective_from desc,created_at desc,id desc limit 1;
 if found and (a.effective_to is null or now()<a.effective_to) then return a.enabled; end if;
 select * into a from public.savings_action_availability
 where action_code=p_action_code and scope_type='GLOBAL' and effective_from<=now()
 order by effective_from desc,created_at desc,id desc limit 1;
 if found then return a.enabled and (a.effective_to is null or now()<a.effective_to); end if;
 if p_action_code='JOIN' then
   select entry_mode into mode from public.savings_operation_settings order by created_at desc,id desc limit 1;
   return coalesce(mode,'ALL_YEAR')='ALL_YEAR';
 end if;
 return false;
end $function$

CREATE OR REPLACE FUNCTION public.savings_canonical_user_projection(p_participant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; composition jsonb;
begin
 result:=savings_period_private.projection_before(p_participant_id);
 composition:=savings_period_private.composition(p_participant_id,null);
 -- No raw transaction IDs or administrative attribution controls in self DTO.
 return result||jsonb_build_object('period_balances',composition-array['movements','version']);
end $function$

CREATE OR REPLACE FUNCTION savings_period_private.projection_before(p_participant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.savings_participants%rowtype; e public.savings_enrollments%rowtype;
 c public.savings_balance_certifications%rowtype; r public.savings_review_records%rowtype;
 plan public.savings_contribution_plans%rowtype; d jsonb; accepted jsonb; related jsonb:='[]'; transition jsonb; bal jsonb; hist jsonb; annual jsonb;
 withdrawals jsonb; upcoming jsonb; actions jsonb; requests jsonb; changes jsonb;
 today date:=public.savings_operation_today(); published boolean; effective_status text;
begin
 select * into p from public.savings_participants where id=p_participant_id;
 if not found or p.identity_status<>'RESOLVED' or p.certification_status<>'CERTIFIED' or p.data_classification<>'CANONICAL'
  or not exists(select 1 from public.affiliates a where a.id=p.affiliate_id and a.numero_control=p.legacy_folio and not coalesce(a.is_archived,false))
  or (select count(*) from public.affiliates where numero_control=p.legacy_folio and not coalesce(is_archived,false))<>1 then
  raise exception 'SAVINGS_EXACT_IDENTITY_REQUIRED' using errcode='55000';
 end if;
 select * into c from public.savings_balance_certifications where participant_id=p.id;
 if c.id is not null then
  select * into r from public.savings_review_records where id=c.record_id;
  select a.after_data->'source_snapshot' into accepted from public.savings_audit_events a where a.participant_id=p.id and a.action='ADJUST_CONFIRMED_BALANCE' order by a.id desc limit 1;
  accepted:=coalesce(accepted,c.source_snapshot);related:=coalesce(accepted->'related','[]');
  d:=(accepted->'source')||(accepted->'proposal');
  if d->>'A' is distinct from p.legacy_folio then raise exception 'SAVINGS_EXACT_IDENTITY_REQUIRED';end if;
 elsif p.import_batch_id is not null then raise exception 'SAVINGS_CERTIFICATION_REQUIRED';
 end if;
 if exists(select 1 from public.savings_transactions where participant_id=p.id and (data_classification<>'CANONICAL' or effective_date>today)) then
  raise exception 'SAVINGS_NONCANONICAL_MOVEMENTS' using errcode='55000';
 end if;
 select * into e from public.savings_enrollments where participant_id=p.id and data_classification='CANONICAL'
  order by sequence_number desc limit 1;
 -- A future authorized cessation stops deductions only on its effective date.
 -- Keep stored history intact and derive today's state for every user action.
 effective_status:=case when (e.terminated_at at time zone 'America/Hermosillo')::date<=today then 'TERMINATED'
  when e.status='TERMINATED' and (e.terminated_at at time zone 'America/Hermosillo')::date>today then 'ACTIVE' else e.status end;
 select * into plan from public.savings_contribution_plans where enrollment_id=e.id and data_classification='CANONICAL'
  and effective_from<=today and (effective_to is null or effective_to>=today) order by effective_from desc limit 1;
 -- Before the first debit the accepted initial plan is still the person's plan.
 if plan.id is null and effective_status='ACTIVE' then
  select * into plan from public.savings_contribution_plans where enrollment_id=e.id and data_classification='CANONICAL'
   and effective_from>today order by effective_from limit 1;
 end if;
 select to_jsonb(b)||jsonb_build_object('yield',b.yield_amount,'canonical',true,'total_source','CERTIFIED_SAVINGS_TRANSACTIONS')
  into bal from public.savings_participant_balance(p.id)b;
 if (bal->>'capital')::numeric<0 or (bal->>'yield_amount')::numeric<0 then raise exception 'SAVINGS_NEGATIVE_COMPONENT';end if;

 -- Closed source summaries retain their exact period. September receipts never
 -- appear under the old June subtotal. Opening credits are excluded throughout.
 with corrections as (
  select sum(coalesce(public.savings_panel_number(d->(f->>'key')),0)-coalesce(public.savings_panel_number(accepted->'source'->(f->>'key')),0)) amount
  from jsonb_array_elements(coalesce(r.field_defs,'[]'))f
  where f->>'label' ~ '^\d{4}-\d{2}-\d{2}' and f->>'label' like '%Descuento registrado%'
   and left(f->>'label',10)::date between '2026-01-30'::date and '2026-06-30'::date
 ), historical as (
  select 2025 as period_year,2 semester,'2025'::text as year,'2025'::text label,'Subtotal hasta 2025'::text subtotal_label,
   public.savings_panel_number(d->'DP') capital,public.savings_panel_number(d->'DQ') yield_amount,true closed
  union all select 2026,1,'2026','2026 - Enero a junio','Subtotal a junio 2026',
   public.savings_panel_number(d->'DS')+coalesce((select amount from corrections),0),public.savings_panel_number(d->'DT'),true
 ), subsequent_history as (
  select left(f->>'label',10)::date as day,public.savings_panel_number(d->(f->>'key')) amount
  from jsonb_array_elements(coalesce(r.field_defs,'[]'))f where f->>'label' ~ '^\d{4}-\d{2}-\d{2}'
   and f->>'label' like '%Descuento registrado%' and left(f->>'label',10)::date>'2026-06-30'::date
   and public.savings_panel_number(d->(f->>'key')) is not null
 ), new_money as (
  select extract(year from day)::int period_year,case when extract(month from day)<=6 then 1 else 2 end semester,sum(amount) capital
  from (
   select day,amount from subsequent_history
   union all
   select contribution_date,case direction when 'CREDIT' then amount else -amount end from public.savings_transactions
    where participant_id=p.id and data_classification='CANONICAL' and component='CAPITAL' and contribution_date is not null
     and effective_date<=today and (c.id is null or contribution_date>c.cutoff_on)
  ) q group by 1,2
 ), yields as (
  select yp.period_year,yp.semester,a.approved_amount amount,yp.productive_enabled and a.status in ('CREDITED','EXCLUDED') closed
  from public.savings_yield_allocations a join public.savings_yield_periods yp on yp.id=a.yield_period_id
  where a.participant_id=p.id and a.status in ('CREDITED','EXCLUDED')
   and (p.historical_yield_reconciled_through is null or yp.starts_on>p.historical_yield_reconciled_through)
 ), subsequent as (
  select coalesce(n.period_year,y.period_year) period_year,coalesce(n.semester,y.semester) semester,
   coalesce(n.capital,0) capital,y.amount yield_amount,coalesce(y.closed,false) closed
  from new_money n full join yields y using(period_year,semester)
 ), periods as (
  select * from historical where capital is not null or yield_amount is not null
  union all
  select period_year,semester,period_year::text||'-S'||semester,
   period_year::text||case semester when 1 then ' - Enero a junio' else ' - Julio a diciembre' end,
   'Subtotal registrado',capital,yield_amount,closed from subsequent
 ) select coalesce(jsonb_agg(jsonb_build_object('year',year,'label',label,'subtotal_label',subtotal_label,'closed',closed,
   'capital',capital,'yield',yield_amount,'period_state',case when closed then 'CLOSED' else 'RECORDED' end)
   order by period_year desc,semester desc),'[]') into annual from periods;

 with recorded as (
  select r.id::text||':'||(f->>'key') id,left(f->>'label',10)::date effective_date,
   public.savings_panel_number(d->(f->>'key')) amount,'HISTORICAL_RECORDED'::text source,
   case when f->>'key'='AR' then 'CONTRIBUTION_WITH_INCLUDED_YIELD' else 'CONTRIBUTION' end transaction_type
  from jsonb_array_elements(coalesce(r.field_defs,'[]'))f where f->>'label' ~ '^\d{4}-\d{2}-\d{2}'
   and f->>'label' like '%Descuento registrado%' and public.savings_panel_number(d->(f->>'key'))>0
  union all
  select o.id::text,o.contribution_date,o.actual_amount,'CONFIRMED_RECEIPT','CONTRIBUTION' from (
   select distinct on(enrollment_id,contribution_date) o.* from public.savings_contribution_overrides o
   join public.savings_enrollments en on en.id=o.enrollment_id where en.participant_id=p.id
   and (c.id is null or o.contribution_date>c.cutoff_on) and o.contribution_date<=today
   order by enrollment_id,contribution_date,version_number desc
  )o
 ) select coalesce(jsonb_agg(to_jsonb(v) order by effective_date desc,id),'[]') into hist from recorded v;
 with w as (
  select q.id::text id,public.savings_panel_date(v.d->>'D') effective_date,
   public.savings_panel_number(v.d->'G') amount,v.d->>'E' withdrawal_kind,
   v.d->>'F' continue_saving,v.d->>'H' status,'HISTORICAL_RECORDED'::text source
  from public.savings_review_records q join jsonb_array_elements(related) a on a->>'id'=q.id::text
  cross join lateral(select (a->'source')||(a->'proposal') d)v
  where q.source_sheet='Solicitud de retiro' and q.source_folio=p.legacy_folio and v.d->>'A'=p.legacy_folio
  union all
  select q.id::text,(q.settled_at at time zone 'America/Hermosillo')::date,q.requested_amount,q.withdrawal_kind,q.continue_saving::text,q.status,'CANONICAL'
  from public.savings_requests q where q.participant_id=p.id and q.data_classification='CANONICAL' and q.status='SETTLED'
   and q.request_type in ('WITHDRAW','EXTRAORDINARY_WITHDRAWAL','TERMINATE')
 ) select coalesce(jsonb_agg(to_jsonb(w) order by effective_date desc,id),'[]') into withdrawals from w;
 select coalesce(jsonb_agg(jsonb_build_object('contribution_date',s.contribution_date,'expected_amount',s.expected_amount,
  'process_snapshot',s.process_snapshot,'source','DATED_SAVINGS_PLAN')||savings_automatic_private.scheduled(e.id,s.contribution_date) order by s.contribution_date),'[]') into upcoming
  from public.generate_savings_schedule(e.id,today+1,(today+interval '12 months')::date)s where effective_status in ('ACTIVE','TERMINATION_PENDING');
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'folio',q.folio,'request_type',q.request_type,'withdrawal_kind',q.withdrawal_kind,
  'requested_amount',q.requested_amount,'new_contribution_amount',q.new_contribution_amount,'continue_saving',q.continue_saving,
  'status',q.status,'effective_from',q.effective_from,'submitted_at',q.submitted_at,'settled_at',q.settled_at) order by q.submitted_at desc),'[]') into requests
  from public.savings_requests q where q.participant_id=p.id and q.data_classification='CANONICAL';
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'effective_date',public.savings_panel_date(v.d->>'B'),
  'old_amount',public.savings_panel_number(v.d->'C'),'new_amount',public.savings_panel_number(v.d->'D'),
  'applied',v.d->>'E','source','HISTORICAL_RECORDED') order by q.source_row desc),'[]') into changes
  from public.savings_review_records q join jsonb_array_elements(related) a on a->>'id'=q.id::text
  cross join lateral(select (a->'source')||(a->'proposal') d)v
  where q.source_sheet='Solicitud Cambio ahorro' and q.source_folio=p.legacy_folio and v.d->>'A'=p.legacy_folio;
 select jsonb_build_object('event_id',ev.id,'previous_amount',ev.conversion_snapshot->'previous_amount','new_amount',ev.conversion_snapshot->'new_amount',
  'effective_from',ev.effective_from,'first_discount_on',ev.conversion_snapshot->'first_discount_on',
  'status',case when ev.effective_from>today then 'SCHEDULED' else 'ACTIVE' end) into transition
 from public.savings_process_change_events ev where ev.participant_id=p.id and ev.status='APPLIED'
  and ev.conversion_snapshot->>'enrollment_id'=e.id::text and ev.conversion_snapshot->>'conversion_rule'='TWO_FORTNIGHTS_TO_ONE_MONTH'
  and (ev.effective_from>today or plan.id::text=ev.conversion_snapshot->>'new_plan_id') order by ev.effective_from desc,ev.reviewed_at desc limit 1;
 select mode='PUBLISHED' into published from public.savings_publication_state where id;
 actions:=jsonb_build_object('JOIN',(e.id is null or effective_status='TERMINATED') and public.savings_effective_action('JOIN',p.id),'CHANGE_AMOUNT',coalesce(effective_status='ACTIVE',false) and public.savings_effective_action('CHANGE_AMOUNT',p.id),
  'WITHDRAW',coalesce((bal->>'available')::numeric>0,false) and public.savings_effective_action('WITHDRAW',p.id),
  'TERMINATE',coalesce(effective_status='ACTIVE',false));
 return jsonb_build_object('schema_version','SAVINGS_CERTIFIED_SELF_V1','authority','SUPABASE','projection','CERTIFIED_OPERATION',
  'cutover_status',case when published then 'PUBLISHED' else 'PRIVATE_PREVIEW' end,'canonical_ledger_used',true,'yield_calculated',false,
  'participant',jsonb_build_object('id',p.id,'legacy_folio',p.legacy_folio,'identity_status',p.identity_status,'participant_type',p.participant_type,'current_process',p.current_process),
  'enrollment',case when e.id is null then null else jsonb_build_object('id',e.id,'status',case effective_status when 'ACTIVE' then 'Ahorrando' when 'TERMINATED' then 'Dejó de ahorrar' else 'En revisión' end,
   'enrollment_started_at',e.first_actual_contribution_date,'plan_started_at',(e.enrollment_started_at at time zone 'America/Hermosillo')::date,
   'current_contribution_amount',plan.amount,'frequency',case when plan.process_snapshot='JUB' then 'MONTHLY' when plan.process_snapshot in ('PROCESS_1','PROCESS_3') then 'TWICE_MONTHLY' end) end,
  'balances',bal,'annual',annual,'history',hist,'upcoming',upcoming,'withdrawals',withdrawals,'requests',requests,'plan_changes',changes,'retirement_transition',transition,
  'beneficiaries',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'full_name',b.full_name,'relationship',b.relationship,'percentage',b.percentage) order by b.id)
   from public.savings_beneficiary_versions v join public.savings_beneficiaries b on b.version_id=v.id where v.participant_id=p.id and v.status='ACTIVE'),'[]'),
  'actions',actions,'write_capabilities',jsonb_build_object('requests',published,'beneficiaries',published and coalesce(effective_status in ('ACTIVE','TERMINATION_PENDING'),false)));
end $function$

CREATE OR REPLACE FUNCTION savings_period_private.composition(p_participant_id uuid, p_as_of date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.savings_participants%rowtype; as_of date:=coalesce(p_as_of,public.savings_operation_today());
 rows jsonb; movements jsonb; bal jsonb; version text; unresolved jsonb; historical_balance jsonb; supported_from date; as_of_complete boolean;
begin
 select * into p from public.savings_participants where id=p_participant_id;
 if p.id is null or p.identity_status<>'RESOLVED' or p.certification_status<>'CERTIFIED' or p.data_classification<>'CANONICAL'
  or not exists(select 1 from public.affiliates a where a.id=p.affiliate_id and a.numero_control=p.legacy_folio and not coalesce(a.is_archived,false))
  or (select count(*) from public.affiliates a where a.numero_control=p.legacy_folio and not coalesce(a.is_archived,false))<>1
 then raise exception 'SAVINGS_EXACT_IDENTITY_REQUIRED' using errcode='55000';end if;
 if as_of>public.savings_operation_today() then raise exception 'SAVINGS_PERIOD_FUTURE_CUTOFF';end if;
 if exists(select 1 from public.savings_transactions t where t.participant_id=p.id and
  (t.data_classification<>'CANONICAL' or t.effective_date>public.savings_operation_today())) then raise exception 'SAVINGS_NONCANONICAL_MOVEMENTS';end if;
 select to_jsonb(b) into bal from public.savings_participant_balance(p.id)b;
 if (bal->>'capital')::numeric<0 or (bal->>'yield_amount')::numeric<0 then raise exception 'SAVINGS_NEGATIVE_COMPONENT';end if;
 select coalesce((select c.cutoff_on from public.savings_balance_certifications c where c.participant_id=p.id),
  (select min(t.effective_date) from public.savings_transactions t where t.participant_id=p.id and t.transaction_type='REGULARIZATION'),
  (select min((e.enrollment_started_at at time zone 'America/Hermosillo')::date) from public.savings_enrollments e where e.participant_id=p.id and e.data_classification='CANONICAL')) into supported_from;
 as_of_complete:=supported_from is not null and as_of>=supported_from;
 with resolved as materialized(select * from savings_period_private.origins(p.id,as_of)),
 amounts as(select o.origin_key,o.component,
  sum(o.amount) filter(where o.direction='CREDIT' and o.economic_type<>'WITHDRAWAL') recognized,
  sum(case when o.direction='DEBIT' then o.amount else -o.amount end) filter(where o.economic_type='WITHDRAWAL') withdrawn,
  sum(o.amount) filter(where o.direction='DEBIT' and o.economic_type<>'WITHDRAWAL') adjustments,
  sum(case o.direction when 'CREDIT' then o.amount else -o.amount end) remainder
  from resolved o group by o.origin_key,o.component),
 -- Unknown credits never prove which previously recognized origin paid an
 -- unknown debit. Keep debit uncertainty independent of unidentified inflows.
 pending as(select component,sum(amount) amount from resolved
  where origin_key like 'UNALLOCATED_%' and (direction='DEBIT' or origin_key='UNALLOCATED_REVERSAL') group by component)
 select coalesce(jsonb_agg(jsonb_build_object('origin_key',a.origin_key,'component',a.component,
  'period_year',case when a.origin_key ~ '^[12][0-9]{3}' then left(a.origin_key,4)::integer end,
  'semester',case when a.origin_key ~ '-S[12]$' then right(a.origin_key,1)::integer end,
  'recognized',coalesce(a.recognized,0),'withdrawn',coalesce(a.withdrawn,0),'adjustments',coalesce(a.adjustments,0),
  'remaining_before_unallocated',a.remainder,'remaining',case when coalesce(u.amount,0)>0 then null else a.remainder end,
  'origin_state',case when a.origin_key='OPENING' then 'OPENING_UNALLOCATED' when a.origin_key like 'UNALLOCATED_%' then 'REQUIRES_ALLOCATION' else 'CLASSIFIED' end)
  order by a.origin_key,a.component),'[]') into rows from amounts a left join pending u using(component);
 select coalesce(jsonb_agg(jsonb_build_object('transaction_id',t.id,'component',t.component,'type',t.transaction_type,
  'effective_date',t.effective_date,'amount',t.amount,'direction',t.direction,
  'can_classify',not exists(select 1 from savings_period_private.attribution_events e where e.transaction_id=t.id)
   and ((t.transaction_type='REGULARIZATION' and t.direction='CREDIT') or (t.transaction_type='WITHDRAWAL' and t.direction='DEBIT')),
  'origins',(select jsonb_agg(jsonb_build_object('origin_key',o.origin_key,'amount',o.amount) order by o.origin_key)
   from savings_period_private.origins(p.id,as_of)o where o.transaction_id=t.id)) order by t.effective_date,t.id),'[]') into movements
 from public.savings_transactions t where t.participant_id=p.id and t.effective_date<=as_of;
 select jsonb_build_object('capital',coalesce(sum(case when t.component='CAPITAL' then case t.direction when 'CREDIT' then t.amount else -t.amount end end),0),
  'yield_amount',coalesce(sum(case when t.component='YIELD' then case t.direction when 'CREDIT' then t.amount else -t.amount end end),0),
  'total',coalesce(sum(case t.direction when 'CREDIT' then t.amount else -t.amount end),0))
 into historical_balance from public.savings_transactions t where t.participant_id=p.id and t.effective_date<=as_of;
 if not as_of_complete then historical_balance:=jsonb_build_object('capital',null,'yield_amount',null,'total',null);end if;
 select coalesce(jsonb_agg(v),'[]') into unresolved from jsonb_array_elements(rows)v where v->>'origin_state'='REQUIRES_ALLOCATION';
 version:=md5(jsonb_build_array(p,as_of,bal,rows,movements)::text);
 return jsonb_build_object('schema_version','SAVINGS_PERIOD_COMPOSITION_V1','participant_id',p.id,'folio',p.legacy_folio,
  'as_of',as_of,'version',version,'balances',bal,'as_of_balance',historical_balance,'as_of_complete',as_of_complete,'as_of_supported_from',supported_from,'periods',rows,'movements',movements,
  'unresolved',unresolved,'complete',jsonb_array_length(unresolved)=0,
  'historical_note','La apertura sin periodo comprobado no se suma nuevamente. El disponible se valida por componente; las retenciones no se distribuyen entre periodos.');
end $function$

CREATE OR REPLACE FUNCTION public.savings_panel_date(v text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d date; begin
 if v ~ '^\d{4}-\d{2}-\d{2}$' then d:=v::date;
 elsif v ~ '^\d{1,2}/\d{1,2}/\d{4}$' then
  d:=make_date(split_part(v,'/',3)::int,split_part(v,'/',2)::int,split_part(v,'/',1)::int);
 end if; return d;
 exception when datetime_field_overflow or invalid_datetime_format then return null;
end $function$

CREATE OR REPLACE FUNCTION savings_automatic_private.scheduled(p_enrollment_id uuid, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s record;i savings_automatic_private.instructions%rowtype;changed boolean;
begin
 select * into s from public.generate_savings_schedule(p_enrollment_id,p_date,p_date);
 select * into i from savings_automatic_private.instructions where enrollment_id=p_enrollment_id and contribution_date=p_date order by version desc limit 1;
 if s.plan_id is null then return jsonb_build_object('scheduled_amount',null,'scheduled_version',coalesce(i.version,0),'scheduled_source',case when i.id is null then 'PLAN' else 'MANUAL_INSTRUCTION' end,'scheduled_status','PLAN_CHANGED');end if;
 changed:=(select count(*)<>1 or bool_or(data_classification<>'CANONICAL') from public.savings_contribution_plans where enrollment_id=p_enrollment_id and effective_from<=p_date and (effective_to is null or effective_to>=p_date))
  or (i.id is not null and (i.plan_id is distinct from s.plan_id or i.plan_hash is distinct from savings_automatic_private.plan_hash(s.plan_id)));
 return jsonb_build_object('scheduled_amount',case when changed then null else coalesce(i.amount,s.expected_amount) end,
  'scheduled_version',coalesce(i.version,0),'scheduled_source',case when i.id is null then 'PLAN' else 'MANUAL_INSTRUCTION' end,
  'scheduled_status',case when changed then 'PLAN_CHANGED' when i.id is null then 'PLAN' else 'EDITED' end,
  'instruction_id',i.id,'plan_id',s.plan_id,'plan_hash',savings_automatic_private.plan_hash(s.plan_id));
end $function$

CREATE OR REPLACE FUNCTION public.savings_next_contribution_date(p_from date, p_process text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare d date;
begin
 if p_from is null or p_process is null or p_process not in ('JUB','PROCESS_1','PROCESS_3') then
   raise exception 'SAVINGS_CALENDAR_INPUT_INVALID' using errcode='22023';
 end if;
 for i in 0..35 loop
   d:=p_from+i;
   if (p_process='JUB' and extract(day from d)=5)
     or (p_process<>'JUB' and (extract(day from d)=15 or
       (extract(month from d)=2 and extract(day from d)=28) or
       (extract(month from d)<>2 and extract(day from d)=30))) then return d; end if;
 end loop;
 raise exception 'SAVINGS_CALENDAR_DATE_NOT_FOUND';
end $function$

CREATE OR REPLACE FUNCTION savings_period_private.resolve_origin(p_transaction_id uuid, p_as_of date, p_path uuid[] DEFAULT ARRAY[]::uuid[])
 RETURNS TABLE(origin_key text, amount numeric, economic_type text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.savings_transactions%rowtype; original public.savings_transactions%rowtype;
 source_rows jsonb; source_row jsonb; resolved_key text; reversed numeric;
begin
 select * into t from public.savings_transactions where id=p_transaction_id and data_classification='CANONICAL' and effective_date<=p_as_of;
 if t.id is null then return;end if;
 if t.id=any(p_path) or cardinality(p_path)>100 then
  return query select 'UNALLOCATED_REVERSAL'::text,t.amount::numeric,t.transaction_type;return;
 end if;
 if exists(select 1 from savings_period_private.attribution_events e where e.transaction_id=t.id) then
  return query select s.origin_key,s.amount::numeric,t.transaction_type from savings_period_private.attribution_events e
   join savings_period_private.attribution_slices s on s.event_id=e.id where e.transaction_id=t.id;
  return;
 end if;
 if t.transaction_type='REVERSAL' then
  select * into original from public.savings_transactions where id=t.reversal_of_transaction_id and data_classification='CANONICAL';
  select coalesce(sum(r.amount),0) into reversed from public.savings_transactions r where r.reversal_of_transaction_id=original.id
   and r.transaction_type='REVERSAL' and r.data_classification='CANONICAL' and r.effective_date<=p_as_of;
  if original.id is null or original.participant_id<>t.participant_id or original.component<>t.component
   or original.direction=t.direction or original.effective_date>t.effective_date or reversed>original.amount then
   return query select 'UNALLOCATED_REVERSAL'::text,t.amount::numeric,'REVERSAL'::text;return;
  end if;
  select jsonb_agg(to_jsonb(o)) into source_rows from savings_period_private.resolve_origin(original.id,p_as_of,p_path||t.id)o;
  if source_rows is null or exists(select 1 from jsonb_array_elements(source_rows)r where r->>'origin_key' like 'UNALLOCATED_%')
   or (t.amount<>original.amount and jsonb_array_length(source_rows)<>1) then
   return query select 'UNALLOCATED_REVERSAL'::text,t.amount::numeric,'REVERSAL'::text;return;
  end if;
  for source_row in select v from jsonb_array_elements(source_rows)v loop
   return query select source_row->>'origin_key',case when t.amount=original.amount then (source_row->>'amount')::numeric else t.amount end,source_row->>'economic_type';
  end loop;
  return;
 end if;
 if t.component='CAPITAL' and t.contribution_date is not null and
  (t.transaction_type='CONTRIBUTION' or (t.transaction_type='ADJUSTMENT' and t.enrollment_id is not null and exists(
   select 1 from public.savings_transactions c where c.participant_id=t.participant_id and c.enrollment_id=t.enrollment_id
    and c.component='CAPITAL' and c.transaction_type='CONTRIBUTION' and c.data_classification='CANONICAL'
    and c.contribution_date=t.contribution_date and c.effective_date<=t.effective_date))) then
  resolved_key:=extract(year from t.contribution_date)::integer::text||'-S'||case when extract(month from t.contribution_date)<=6 then '1' else '2' end;
 elsif t.transaction_type='YIELD_CREDIT' and t.component='YIELD' and t.direction='CREDIT' then
  select yp.period_year::text||'-S'||yp.semester::text into resolved_key from public.savings_yield_allocations a
   join public.savings_yield_periods yp on yp.id=a.yield_period_id where a.participant_id=t.participant_id and a.status='CREDITED'
    and a.approved_amount=t.amount and t.idempotency_key='PERIOD_YIELD:'||yp.id||':'||t.participant_id;
 end if;
 resolved_key:=coalesce(resolved_key,case when t.transaction_type='WITHDRAWAL' and t.direction='DEBIT' then 'UNALLOCATED_WITHDRAWAL'
  when t.direction='DEBIT' then 'UNALLOCATED_ADJUSTMENT' when t.transaction_type='REGULARIZATION' then 'OPENING' else 'UNALLOCATED_CREDIT' end);
 return query select resolved_key,t.amount::numeric,t.transaction_type;
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_panel(p_tab text DEFAULT 'padron'::text, p_search text DEFAULT ''::text, p_filter text DEFAULT 'todos'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; summary jsonb; people jsonb; rows jsonb; balance_total numeric; mode text; filtered_total integer;
begin
 -- The preserved reader performs permission, scope and duplicate-baseline checks first.
 -- Guards replicated so an unauthorised or invalid call never pays for the projection.
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_PANEL_DENIED' using errcode='42501'; end if;
 if p_tab is null or p_tab not in ('padron','cobranza','solicitudes','revision') or p_filter is null or p_filter not in ('todos','ahorrando','pausado','baja','pendientes','resueltas') or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 50 or length(coalesce(p_search,''))>200 then raise exception 'SAVINGS_PANEL_INVALID'; end if;
 if (select count(distinct batch_id) from public.savings_review_records where source_sheet='Ahorro')>1 then raise exception 'SAVINGS_PANEL_MULTIPLE_BASELINES';end if;
 -- One projection per load, shared by both readers. Previously each computed its own.
 people:=coalesce((select jsonb_agg(v) from public.savings_panel_people() v),'[]'::jsonb);
 result:=public.savings_panel_before_current_summary(p_tab,p_search,p_filter,p_offset,p_limit,people);
 summary:=public.savings_admin_current_summary(people);
 if p_tab in ('padron','revision','cobranza') then
  -- Effective state, filtering and neighbours share this exact reader. Date correction targets stay historical.
  with filtered as materialized(select a from public.savings_admin_filtered_people(p_tab,p_search,p_filter,summary)a),
   page as(select a from filtered order by a->>'nombre',a->>'folio',(a->>'source_row')::int,a->>'id' offset p_offset limit p_limit)
  select coalesce((select jsonb_agg(a) from page),'[]'::jsonb),count(*),
   case when count(*)=count(a->>'saldo') then coalesce(sum((a->>'saldo')::numeric),0) end into rows,filtered_total,balance_total from filtered;
  result:=result||jsonb_build_object('rows',rows,'total',filtered_total,'saldo_total',balance_total);
 end if;
 select s.mode into mode from public.savings_publication_state s where id;
 return result||jsonb_build_object('kpis',(result->'kpis')||(summary->'kpis'),'collection_status',summary->>'collection_status','publication_mode',mode);
end $function$

CREATE OR REPLACE FUNCTION public.savings_panel_before_current_summary(p_tab text DEFAULT 'padron'::text, p_search text DEFAULT ''::text, p_filter text DEFAULT 'todos'::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20, p_people jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; k jsonb; cut timestamptz; collection jsonb;
begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_PANEL_DENIED' using errcode='42501'; end if;
 if p_tab is null or p_tab not in ('padron','cobranza','solicitudes','revision') or p_filter is null or p_filter not in ('todos','ahorrando','pausado','baja','pendientes','resueltas') or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 50 or length(coalesce(p_search,''))>200 then raise exception 'SAVINGS_PANEL_INVALID'; end if;
 if (select count(distinct batch_id) from public.savings_review_records where source_sheet='Ahorro')>1 then raise exception 'SAVINGS_PANEL_MULTIPLE_BASELINES';end if;
 select max(observed_at) into cut from public.savings_review_batches;
 with people as materialized (select a from jsonb_array_elements(coalesce(p_people,(select jsonb_agg(v) from public.savings_panel_people() v),'[]'::jsonb)) a), next_day as (select min((a->>'prox')::date) d from people)
 select jsonb_build_object('total',case when count(*)=count(a->>'saldo') then coalesce(sum((a->>'saldo')::numeric),0) end,'activos',count(*) filter(where a->>'estado'='ahorrando'),
  'padron',count(*),'afiliados',(select count(*) from public.affiliates where not coalesce(is_archived,false)),
  'prox',(select d from next_day),'porRecibir',sum((a->>'porRecibir')::numeric) filter(where (a->>'prox')::date=(select d from next_day)),
  'altas',count(*) filter(where date_trunc('month',(a->>'inicio')::date)=date_trunc('month',cut at time zone 'America/Hermosillo')),
  'bajas',count(*) filter(where date_trunc('month',(a->>'bajaAt')::date)=date_trunc('month',cut at time zone 'America/Hermosillo')),
  'incidencias',count(*) filter(where (a->>'needs_review')::boolean and a->>'status'<>'RESOLVED'),
  'pendientes',(select count(*) from public.savings_review_records r where r.status<>'RESOLVED' and r.source_sheet in ('Solicitud Cambio ahorro','Solicitud de retiro')),
  'solicitudes_estado_pendiente',(select count(*) from public.savings_review_records r where r.status<>'RESOLVED' and (r.source_sheet='Solicitud Cambio ahorro' and (r.source_data||r.proposed_data)->>'E' is distinct from 'TRUE' or r.source_sheet='Solicitud de retiro' and (r.source_data||r.proposed_data)->>'H' is distinct from 'Completado')),
  'cobranza',jsonb_build_object('pct',null,'esperado',null,'recibido',null,'fecha',null)) into k from people;
 with dates as materialized (
  select left(f->>'label',10)::date fecha,public.savings_panel_number(r.source_data->(f->>'key')) amount
  from public.savings_review_records r cross join lateral jsonb_array_elements(r.field_defs) f
  where r.source_sheet='Ahorro' and f->>'label' ~ '^\d{4}-\d{2}-\d{2}' and f->>'label' like '%Descuento registrado%'
 ), last_day as(select max(fecha) d from dates)
 select jsonb_build_object('fecha',(select d from last_day),'recibido',sum(amount),'esperado',null,'pct',null,'sin_importe',count(*) filter(where amount is null)) into collection from dates where fecha=(select d from last_day);
 k:=jsonb_set(k,'{cobranza}',collection);
 if p_tab in ('padron','revision','cobranza') then
  with people as materialized (select a from jsonb_array_elements(coalesce(p_people,(select jsonb_agg(v) from public.savings_panel_people() v),'[]'::jsonb)) a), filtered as materialized (
   select a from people where
    (coalesce(p_search,'')='' or position(lower(p_search) in lower(coalesce(a->>'nombre','')))>0 or position(p_search in coalesce(a->>'folio',''))>0)
    and (p_tab<>'revision' or ((a->>'needs_review')::boolean or a->>'status'='RESOLVED'))
    and (p_tab<>'cobranza' or a->>'zero_recorded'='true')
    and (p_filter='todos' or p_filter='pendientes' and a->>'status'<>'RESOLVED' or p_filter='resueltas' and a->>'status'='RESOLVED' or p_filter='pausado' and a->>'zero_recorded'='true' or a->>'estado'=p_filter)
  ), page as (select a from filtered order by a->>'nombre',a->>'folio',(a->>'source_row')::int,a->>'id' offset p_offset limit p_limit)
  select jsonb_build_object('rows',coalesce((select jsonb_agg(a) from page),'[]'::jsonb),'total',(select count(*) from filtered),'saldo_total',(select case when count(*)=count(a->>'saldo') then coalesce(sum((a->>'saldo')::numeric),0) end from filtered)) into result;
 else
  with requests as materialized (
   select r.id,r.source_sheet,r.source_row,r.source_folio,
    coalesce((select jsonb_object_agg(e.key,e.value) from jsonb_each(r.source_data) e where e.key=any(case when r.source_sheet='Solicitud de retiro' then array['A','D','E','F','G','H'] else array['A','B','C','D','E'] end)),'{}'::jsonb) source_data,
    coalesce((select jsonb_object_agg(e.key,e.value) from jsonb_each(r.proposed_data) e where e.key=any(case when r.source_sheet='Solicitud de retiro' then array['A','D','E','F','G','H'] else array['A','B','C','D','E'] end)),'{}'::jsonb) proposed_data,
    r.status,r.version,r.issues,
    (r.source_data||r.proposed_data)->>'A' is distinct from r.source_folio identity_pending,
    public.savings_review_identity(r.source_folio) identity,
    case when r.source_sheet='Solicitud de retiro' then public.savings_panel_date(r.source_data->>'D') else public.savings_panel_date(r.source_data->>'B') end fecha
   from public.savings_review_records r where r.source_sheet in ('Solicitud de retiro','Solicitud Cambio ahorro')
    and (coalesce(p_search,'')='' or position(p_search in coalesce(r.source_folio,''))>0 or position(lower(p_search) in lower(public.savings_review_identity(r.source_folio)->>'name'))>0)
    and (p_filter='todos' or p_filter='resueltas' and r.status='RESOLVED' or p_filter='pendientes' and r.status<>'RESOLVED')
  ), page as(select * from requests order by fecha desc nulls last,source_sheet,source_row,id offset p_offset limit p_limit)
  select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'::jsonb),'total',(select count(*) from requests)) into result;
 end if;
 return result||jsonb_build_object('kpis',k,'cutoff',cut,'publication','PRIVATE_REVIEW_ONLY','can_write',public.savings_review_edit_allowed(),'can_identity',public.savings_review_identity_allowed(),'collection_status','EXPECTED_HISTORY_UNCERTIFIED');
end $function$
